import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import {
  LayoutGroup,
  motion,
  MotionConfig,
  useReducedMotion,
} from "framer-motion";
import { cn } from "@/lib/utils";

const wensityCardSurfaceClass = cn(
  "relative isolate overflow-hidden rounded-2xl",
  "border border-black/[0.08] bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#ffffff_0%,#f4f4f5_72%)] [box-shadow:0_1px_2px_rgba(0,0,0,.06),0_8px_24px_-12px_rgba(0,0,0,.08)]",
  "dark:border-white/[0.06] dark:bg-[radial-gradient(ellipse_90%_70%_at_50%_-10%,#15151b_0%,#0a0a0b_72%)] dark:[box-shadow:0_1px_2px_rgba(0,0,0,.4),0_8px_24px_-12px_rgba(0,0,0,.6)]",
);

export type RadioGroupSize = "sm" | "md" | "lg";
export type RadioGroupVariant = "orb" | "command" | "segment" | "tile";
export type RadioGroupOrientation = "vertical" | "horizontal";

export interface RadioGroupProps
  extends Omit<React.HTMLAttributes<HTMLFieldSetElement>, "defaultValue" | "onChange"> {
  value?: string;
  defaultValue?: string;
  onValueChange?: (
    value: string,
    event: React.ChangeEvent<HTMLInputElement>,
  ) => void;
  name?: string;
  label?: React.ReactNode;
  description?: React.ReactNode;
  error?: React.ReactNode;
  radioSize?: RadioGroupSize;
  variant?: RadioGroupVariant;
  orientation?: RadioGroupOrientation;
  disabled?: boolean;
  children: React.ReactNode;
}

export interface RadioOptionProps
  extends Omit<
    React.InputHTMLAttributes<HTMLInputElement>,
    "checked" | "defaultChecked" | "name" | "onChange" | "size" | "type" | "value"
  > {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  leading?: React.ReactNode;
  trailing?: React.ReactNode;
  radioSize?: RadioGroupSize;
  variant?: RadioGroupVariant;
  fullWidth?: boolean;
  containerClassName?: string;
  controlClassName?: string;
  labelClassName?: string;
  descriptionClassName?: string;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
}

export interface RadioCardProps extends RadioOptionProps {
  eyebrow?: React.ReactNode;
}

type RadioGroupContextValue = {
  name: string;
  value?: string;
  setValue: (value: string, event: React.ChangeEvent<HTMLInputElement>) => void;
  radioSize: RadioGroupSize;
  variant: RadioGroupVariant;
  disabled?: boolean;
  error?: React.ReactNode;
  orbIndicatorLayoutId?: string;
};

const RadioGroupContext = React.createContext<RadioGroupContextValue | null>(
  null,
);

const controlSizes: Record<RadioGroupSize, string> = {
  sm: "size-4",
  md: "size-[18px]",
  lg: "size-5",
};

const segmentSizes: Record<RadioGroupSize, string> = {
  sm: "min-h-8 px-3 text-[12px]",
  md: "min-h-9 px-3.5 text-[13px]",
  lg: "min-h-10 px-4 text-sm",
};

const labelSizes: Record<RadioGroupSize, string> = {
  sm: "text-[13px]",
  md: "text-sm",
  lg: "text-[15px]",
};

const rowGap: Record<RadioGroupSize, string> = {
  sm: "gap-2.5",
  md: "gap-3",
  lg: "gap-3.5",
};

const controlOffset: Record<RadioGroupSize, string> = {
  sm: "mt-px",
  md: "mt-0.5",
  lg: "mt-0.5",
};

const focusRing = cn(
  "peer-focus-visible:outline-none",
  "peer-focus-visible:ring-2 peer-focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)]",
  "peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-[var(--background)]",
);

const smoothSurface =
  "transition-[background-color,border-color,box-shadow,color,opacity] duration-[240ms] ease-[cubic-bezier(0.16,1,0.3,1)] motion-reduce:transition-none";

const radioIndicatorTransition = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;

const RADIO_GROUP_STYLE_ID = "wensity-radio-group-styles-v2";
const EASE_OUT_CSS = "cubic-bezier(0.16, 1, 0.3, 1)";
const EASE_DRAWER_CSS = "cubic-bezier(0.32, 0.72, 0, 1)";

function ensureRadioGroupStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(RADIO_GROUP_STYLE_ID)) return;

  document.getElementById("wensity-radio-group-styles-v1")?.remove();

  const style = document.createElement("style");
  style.id = RADIO_GROUP_STYLE_ID;
  style.textContent = `
    [data-slot="radio-orb-shell"] {
      transition:
        border-color 280ms ${EASE_OUT_CSS},
        box-shadow 280ms ${EASE_OUT_CSS};
    }

    [data-slot="radio-command-shell"] {
      transition:
        border-color 280ms ${EASE_OUT_CSS},
        box-shadow 280ms ${EASE_OUT_CSS},
        background-color 280ms ${EASE_OUT_CSS};
    }

    [data-slot="radio-command-check"] {
      transform: scale(0.92);
      opacity: 0;
      transition:
        transform 240ms ${EASE_DRAWER_CSS},
        opacity 200ms ${EASE_OUT_CSS};
    }

    [data-radio-mark][data-state="checked"] [data-slot="radio-command-check"] {
      transform: scale(1);
      opacity: 1;
      transition-duration: 260ms, 220ms;
    }

    [data-radio-mark][data-state="unchecked"] [data-slot="radio-command-check"] {
      transform: scale(0.92);
      opacity: 0;
      transition-duration: 180ms, 140ms;
    }

    [data-slot="radio-command-check-path"] {
      stroke-dasharray: 1;
      stroke-dashoffset: 1;
      transition: stroke-dashoffset 280ms ${EASE_OUT_CSS} 80ms;
    }

    [data-radio-mark][data-state="checked"] [data-slot="radio-command-check-path"] {
      stroke-dashoffset: 0;
      transition-duration: 260ms;
      transition-delay: 70ms;
    }

    [data-radio-mark][data-state="unchecked"] [data-slot="radio-command-check-path"] {
      stroke-dashoffset: 1;
      transition-duration: 160ms;
      transition-delay: 0ms;
    }

    [data-slot="radio-segment-indicator"] {
      transition: transform 280ms ${EASE_DRAWER_CSS};
    }

    [data-slot="radio-segment-indicator"][data-orientation="vertical"] {
      transition-duration: 260ms;
    }

    [data-slot="radio-segment-label"] {
      transition: color 240ms ${EASE_OUT_CSS};
    }

    [data-slot="radio-card-shell"] {
      transition:
        border-color 280ms ${EASE_OUT_CSS},
        box-shadow 280ms ${EASE_OUT_CSS};
    }

    [data-slot="radio-card-check-shell"] {
      transition:
        border-color 260ms ${EASE_OUT_CSS},
        background-color 260ms ${EASE_OUT_CSS};
    }

    [data-slot="radio-card-check"] {
      opacity: 0;
      transform: scale(0.92);
      transition:
        opacity 200ms ${EASE_OUT_CSS},
        transform 240ms ${EASE_DRAWER_CSS};
    }

    [data-radio-card][data-state="checked"] [data-slot="radio-card-check"] {
      opacity: 1;
      transform: scale(1);
      transition-duration: 220ms, 260ms;
    }

    [data-radio-card][data-state="unchecked"] [data-slot="radio-card-check"] {
      opacity: 0;
      transform: scale(0.92);
      transition-duration: 140ms, 180ms;
    }

    [data-slot="radio-card-check-path"] {
      stroke-dasharray: 1;
      stroke-dashoffset: 1;
      transition: stroke-dashoffset 260ms ${EASE_OUT_CSS} 70ms;
    }

    [data-radio-card][data-state="checked"] [data-slot="radio-card-check-path"] {
      stroke-dashoffset: 0;
      transition-duration: 280ms;
      transition-delay: 80ms;
    }

    [data-radio-card][data-state="unchecked"] [data-slot="radio-card-check-path"] {
      stroke-dashoffset: 1;
      transition-duration: 150ms;
      transition-delay: 0ms;
    }

    @media (prefers-reduced-motion: reduce) {
      [data-slot="radio-orb-shell"],
      [data-slot="radio-command-shell"],
      [data-slot="radio-command-check"],
      [data-slot="radio-command-check-path"],
      [data-slot="radio-segment-indicator"],
      [data-slot="radio-segment-label"],
      [data-slot="radio-card-shell"],
      [data-slot="radio-card-check-shell"],
      [data-slot="radio-card-check"],
      [data-slot="radio-card-check-path"] {
        transition-duration: 0ms !important;
        transition-delay: 0ms !important;
      }

      [data-radio-mark][data-state="checked"] [data-slot="radio-command-check"],
      [data-radio-card][data-state="checked"] [data-slot="radio-card-check"] {
        opacity: 1;
        transform: none;
      }

      [data-radio-mark][data-state="unchecked"] [data-slot="radio-command-check"],
      [data-radio-card][data-state="unchecked"] [data-slot="radio-card-check"] {
        opacity: 0;
        transform: none;
      }

      [data-radio-mark][data-state="checked"] [data-slot="radio-command-check-path"],
      [data-radio-card][data-state="checked"] [data-slot="radio-card-check-path"] {
        stroke-dashoffset: 0;
      }

      [data-radio-mark][data-state="unchecked"] [data-slot="radio-command-check-path"],
      [data-radio-card][data-state="unchecked"] [data-slot="radio-card-check-path"] {
        stroke-dashoffset: 1;
      }
    }
  `;
  document.head.appendChild(style);
}

function getOptionValue(child: React.ReactNode): string | undefined {
  if (!React.isValidElement(child)) return undefined;
  const props = child.props as { value?: string };
  return typeof props.value === "string" ? props.value : undefined;
}

function getSegmentIndex(children: React.ReactNode, selectedValue?: string) {
  const values = React.Children.toArray(children)
    .map(getOptionValue)
    .filter((value): value is string => value !== undefined);

  const selectedIndex = values.findIndex((value) => value === selectedValue);
  return {
    count: values.length,
    index: selectedIndex >= 0 ? selectedIndex : 0,
  };
}

function RadioOrbMark({
  checked,
  radioSize,
  orbIndicatorLayoutId,
}: {
  checked: boolean;
  radioSize: RadioGroupSize;
  orbIndicatorLayoutId?: string;
}) {
  const reduceMotion = useReducedMotion();

  return (
    <span
      data-radio-mark
      data-state={checked ? "checked" : "unchecked"}
      aria-hidden="true"
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center rounded-full border",
        "border-[var(--border-strong)] bg-[var(--background)]",
        "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.32)]",
        focusRing,
        "data-[state=checked]:border-[var(--foreground)]",
        "data-[state=checked]:shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
        "dark:data-[state=checked]:shadow-[0_0_0_3px_color-mix(in_srgb,var(--foreground)_14%,transparent)]",
        controlSizes[radioSize],
      )}
      data-slot="radio-orb-shell"
    >
      {checked && orbIndicatorLayoutId ? (
        <motion.span
          layoutId={orbIndicatorLayoutId}
          transition={reduceMotion ? { duration: 0 } : radioIndicatorTransition}
          className="absolute inset-[5px] rounded-full bg-[var(--foreground)]"
        />
      ) : null}
    </span>
  );
}

function RadioMark({
  checked,
  variant,
  radioSize,
  orbIndicatorLayoutId,
}: {
  checked: boolean;
  variant: RadioGroupVariant;
  radioSize: RadioGroupSize;
  orbIndicatorLayoutId?: string;
}) {
  if (variant === "orb") {
    return (
      <RadioOrbMark
        checked={checked}
        radioSize={radioSize}
        orbIndicatorLayoutId={orbIndicatorLayoutId}
      />
    );
  }

  if (variant === "command") {
    return (
      <span
        data-radio-mark
        data-state={checked ? "checked" : "unchecked"}
        aria-hidden="true"
        className={cn(
          "grid rounded-full border",
          "border-[var(--border-strong)] bg-[var(--background)]",
          "shadow-[0_1px_1px_rgba(0,0,0,0.03)] dark:shadow-[0_1px_2px_rgba(0,0,0,0.35)]",
          focusRing,
          "data-[state=checked]:border-[var(--foreground)] data-[state=checked]:bg-[var(--foreground)] data-[state=checked]:text-[var(--background)]",
          controlSizes[radioSize],
        )}
        data-slot="radio-command-shell"
      >
        <svg
          aria-hidden="true"
          viewBox="0 0 16 16"
          fill="none"
          data-slot="radio-command-check"
          className="m-auto size-3 transform-gpu text-current"
        >
          <path
            data-slot="radio-command-check-path"
            d="M3.4 8.2 6.45 11.25 12.6 4.75"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
          />
        </svg>
      </span>
    );
  }

  return null;
}

function useRadioGroupContext(component: string) {
  const context = React.useContext(RadioGroupContext);
  if (!context) {
    throw new Error(`${component} must be used inside RadioGroup.`);
  }
  return context;
}

export function RadioGroup({
  value,
  defaultValue,
  onValueChange,
  name,
  label,
  description,
  error,
  radioSize = "md",
  variant = "orb",
  orientation = "vertical",
  disabled,
  children,
  className,
  ...props
}: RadioGroupProps) {
  const reactId = React.useId();
  const orbIndicatorLayoutId = React.useId();
  const groupName = name ?? `radio-group-${reactId}`;
  const descriptionId = description ? `${groupName}-description` : undefined;
  const errorId = error ? `${groupName}-error` : undefined;
  const isControlled = value !== undefined;
  const [uncontrolledValue, setUncontrolledValue] = React.useState(defaultValue);
  const selectedValue = isControlled ? value : uncontrolledValue;

  const reduceMotion = useReducedMotion();

  const setValue = React.useCallback(
    (nextValue: string, event: React.ChangeEvent<HTMLInputElement>) => {
      if (!isControlled) setUncontrolledValue(nextValue);
      onValueChange?.(nextValue, event);
    },
    [isControlled, onValueChange],
  );

  const context = React.useMemo<RadioGroupContextValue>(
    () => ({
      name: groupName,
      value: selectedValue,
      setValue,
      radioSize,
      variant,
      disabled,
      error,
      orbIndicatorLayoutId: variant === "orb" ? orbIndicatorLayoutId : undefined,
    }),
    [
      disabled,
      error,
      groupName,
      orbIndicatorLayoutId,
      radioSize,
      selectedValue,
      setValue,
      variant,
    ],
  );

  React.useEffect(() => {
    ensureRadioGroupStyles();
  }, []);

  const segmentLayout =
    variant === "segment" ? getSegmentIndex(children, selectedValue) : null;

  const list = (
    <div
      data-slot="radio-group-list"
      data-orientation={orientation}
      className={cn(
        orientation === "horizontal"
          ? "flex flex-wrap items-stretch gap-2.5"
          : "space-y-2",
        variant === "segment" &&
          cn(
            wensityCardSurfaceClass,
            "relative rounded-xl p-1",
            orientation === "horizontal"
              ? "flex w-full gap-1"
              : "flex flex-col gap-1",
          ),
      )}
      style={
        variant === "segment" && segmentLayout
          ? ({
              "--radio-segment-count": segmentLayout.count,
              "--radio-segment-index": segmentLayout.index,
            } as React.CSSProperties)
          : undefined
      }
    >
      {variant === "segment" && segmentLayout && segmentLayout.count > 0 ? (
        <span
          aria-hidden="true"
          data-slot="radio-segment-indicator"
          data-orientation={orientation}
          className={cn(
            "pointer-events-none absolute rounded-lg",
            "bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))]",
            "dark:bg-[color-mix(in_srgb,var(--foreground)_13%,var(--background))]",
            "shadow-[0_1px_2px_rgba(0,0,0,0.07),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
            "dark:shadow-[0_1px_2px_rgba(0,0,0,0.36),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
            orientation === "horizontal"
              ? "top-1 bottom-1 left-1"
              : "left-1 right-1 top-1",
          )}
          style={
            orientation === "horizontal"
              ? {
                  width:
                    "calc((100% - 0.5rem - (var(--radio-segment-count) - 1) * 0.25rem) / var(--radio-segment-count))",
                  transform:
                    "translate3d(calc(var(--radio-segment-index) * (100% + 0.25rem)), 0, 0)",
                }
              : {
                  height:
                    "calc((100% - 0.5rem - (var(--radio-segment-count) - 1) * 0.25rem) / var(--radio-segment-count))",
                  transform:
                    "translate3d(0, calc(var(--radio-segment-index) * (100% + 0.25rem)), 0)",
                }
          }
        />
      ) : null}
      {children}
    </div>
  );

  return (
    <RadioGroupContext.Provider value={context}>
      <fieldset
        aria-describedby={[descriptionId, errorId].filter(Boolean).join(" ") || undefined}
        aria-invalid={error ? true : undefined}
        disabled={disabled}
        className={cn("space-y-3.5", className)}
        {...props}
      >
        {label || description ? (
          <div className="space-y-1">
            {label ? (
              <legend className="text-sm font-semibold tracking-[-0.015em] text-[var(--foreground)]">
                {label}
              </legend>
            ) : null}
            {description ? (
              <p
                id={descriptionId}
                className="text-[12px] leading-[1.45] text-[var(--muted-foreground)]"
              >
                {description}
              </p>
            ) : null}
          </div>
        ) : null}
        {variant === "orb" ? (
          <MotionConfig
            transition={reduceMotion ? { duration: 0 } : radioIndicatorTransition}
          >
            <LayoutGroup id={`radio-orb-group-${reactId}`}>{list}</LayoutGroup>
          </MotionConfig>
        ) : (
          list
        )}
        {error ? (
          <p
            id={errorId}
            className="text-[12px] leading-[1.45] font-medium text-red-600 dark:text-red-400"
          >
            {error}
          </p>
        ) : null}
      </fieldset>
    </RadioGroupContext.Provider>
  );
}

export const RadioOption = React.forwardRef<HTMLInputElement, RadioOptionProps>(
  (
    {
      value,
      label,
      description,
      leading,
      trailing,
      radioSize,
      variant,
      fullWidth = true,
      disabled,
      className,
      containerClassName,
      controlClassName,
      labelClassName,
      descriptionClassName,
      onChange,
      ...props
    },
    ref,
  ) => {
    const context = useRadioGroupContext("RadioOption");
    const optionSize = radioSize ?? context.radioSize;
    const optionVariant = variant ?? context.variant;
    const optionDisabled = disabled || context.disabled;
    const checked = context.value === value;
    const optionId = React.useId();
    const descriptionId = description ? `radio-option-${optionId}-description` : undefined;

    const handleChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.currentTarget.checked) context.setValue(value, event);
        onChange?.(event);
      },
      [context, onChange, value],
    );

    const input = (
      <input
        ref={ref}
        id={`radio-option-${optionId}`}
        type="radio"
        name={context.name}
        value={value}
        checked={checked}
        disabled={optionDisabled}
        aria-describedby={descriptionId}
        aria-invalid={context.error ? true : undefined}
        onChange={handleChange}
        className="peer sr-only"
        {...props}
      />
    );

    if (optionVariant === "segment") {
      return (
        <label
          data-slot="radio-option"
          data-state={checked ? "checked" : "unchecked"}
          data-disabled={optionDisabled ? "" : undefined}
          className={cn(
            "group/radio relative z-[1] inline-flex cursor-pointer select-none items-center justify-center rounded-lg",
            "font-medium leading-none tracking-[-0.01em]",
            "text-[var(--muted-foreground)]",
            "hover:text-[var(--foreground)]",
            checked && "text-[var(--foreground)]",
            optionDisabled && "cursor-not-allowed opacity-45",
            fullWidth && "flex-1",
            segmentSizes[optionSize],
            containerClassName,
            className,
          )}
        >
          {input}
          <span data-slot="radio-segment-label" className="truncate">
            {label}
          </span>
        </label>
      );
    }

    if (optionVariant === "command") {
      return (
        <label
          data-slot="radio-option"
          data-state={checked ? "checked" : "unchecked"}
          data-disabled={optionDisabled ? "" : undefined}
          className={cn(
            "group/radio flex cursor-pointer select-none items-start p-3.5",
            wensityCardSurfaceClass,
            smoothSurface,
            "data-[state=checked]:border-[color-mix(in_srgb,var(--foreground)_22%,transparent)]",
            "data-[state=checked]:[box-shadow:0_1px_2px_rgba(0,0,0,0.05),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
            "dark:data-[state=checked]:[box-shadow:0_1px_3px_rgba(0,0,0,0.38),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
            !optionDisabled &&
              "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)]",
            optionDisabled && "cursor-not-allowed opacity-45",
            fullWidth ? "w-full" : "w-fit",
            rowGap[optionSize],
            containerClassName,
            className,
          )}
        >
          {input}
          {leading ? (
            <span className="mt-0.5 grid size-8 shrink-0 place-items-center rounded-lg border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] text-[var(--muted-foreground)] [&_svg]:size-4">
              {leading}
            </span>
          ) : null}
          <span className="min-w-0 flex-1">
            <span
              className={cn(
                "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
                labelSizes[optionSize],
                labelClassName,
              )}
            >
              {label}
            </span>
            {description ? (
              <span
                id={descriptionId}
                className={cn(
                  "mt-1 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                  descriptionClassName,
                )}
              >
                {description}
              </span>
            ) : null}
          </span>
          {trailing ? (
            <span className="shrink-0 pt-0.5 text-[12px] font-medium text-[var(--muted-foreground)]">
              {trailing}
            </span>
          ) : null}
          <RadioMark
            checked={checked}
            variant="command"
            radioSize={optionSize}
            orbIndicatorLayoutId={context.orbIndicatorLayoutId}
          />
        </label>
      );
    }

    return (
      <label
        data-slot="radio-option"
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={optionDisabled ? "" : undefined}
        className={cn(
          "group/radio relative flex cursor-pointer select-none items-start",
          rowGap[optionSize],
          fullWidth ? "w-full" : "w-fit",
          optionDisabled && "cursor-not-allowed opacity-45",
          containerClassName,
          className,
        )}
      >
        {input}
        <span className={cn(controlOffset[optionSize], controlClassName)}>
          <RadioMark
            checked={checked}
            variant="orb"
            radioSize={optionSize}
            orbIndicatorLayoutId={context.orbIndicatorLayoutId}
          />
        </span>
        <span className="min-w-0 flex-1 pt-px">
          <span
            className={cn(
              "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
              labelSizes[optionSize],
              labelClassName,
            )}
          >
            {label}
          </span>
          {description ? (
            <span
              id={descriptionId}
              className={cn(
                "mt-1 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                descriptionClassName,
              )}
            >
              {description}
            </span>
          ) : null}
        </span>
        {trailing ? (
          <span className="shrink-0 pt-0.5 text-[12px] font-medium text-[var(--muted-foreground)]">
            {trailing}
          </span>
        ) : null}
      </label>
    );
  },
);

RadioOption.displayName = "RadioOption";

export const RadioCard = React.forwardRef<HTMLInputElement, RadioCardProps>(
  (
    {
      eyebrow,
      leading,
      trailing,
      value,
      label,
      description,
      disabled,
      onChange,
      radioSize = "md",
      variant: _variant,
      fullWidth = true,
      containerClassName,
      controlClassName: _controlClassName,
      className,
      labelClassName,
      descriptionClassName,
      ...props
    },
    ref,
  ) => {
    const context = useRadioGroupContext("RadioCard");
    const checked = context.value === value;
    const optionDisabled = disabled || context.disabled;
    const optionId = React.useId();
    const descriptionId = description ? `radio-card-${optionId}-description` : undefined;

    const handleChange = React.useCallback(
      (event: React.ChangeEvent<HTMLInputElement>) => {
        if (event.currentTarget.checked) context.setValue(value, event);
        onChange?.(event);
      },
      [context, onChange, value],
    );

    return (
      <label
        data-radio-card
        data-state={checked ? "checked" : "unchecked"}
        data-disabled={optionDisabled ? "" : undefined}
        data-slot="radio-card-shell"
        className={cn(
          "group/radio-card relative block cursor-pointer select-none p-4",
          wensityCardSurfaceClass,
          smoothSurface,
          "data-[state=checked]:border-[color-mix(in_srgb,var(--foreground)_28%,transparent)]",
          "data-[state=checked]:[box-shadow:0_1px_2px_rgba(0,0,0,0.06),0_0_0_1px_color-mix(in_srgb,var(--foreground)_8%,transparent)]",
          "dark:data-[state=checked]:[box-shadow:0_1px_3px_rgba(0,0,0,0.38),0_0_0_1px_color-mix(in_srgb,var(--foreground)_12%,transparent)]",
          !optionDisabled &&
            "hover:border-[color-mix(in_srgb,var(--foreground)_18%,transparent)]",
          optionDisabled && "cursor-not-allowed opacity-45",
          fullWidth ? "w-full" : "w-fit",
          containerClassName,
          className,
        )}
      >
        <input
          ref={ref}
          id={`radio-card-${optionId}`}
          type="radio"
          name={context.name}
          value={value}
          checked={checked}
          disabled={optionDisabled}
          aria-describedby={descriptionId}
          aria-invalid={context.error ? true : undefined}
          onChange={handleChange}
          className="peer sr-only"
          {...props}
        />
        <div
          className={cn(
            "pointer-events-none absolute right-3 top-3 grid size-5 place-items-center rounded-full",
            "border border-[var(--border-strong)] bg-[var(--background)] text-[var(--background)]",
            "data-[state=checked]:border-[var(--foreground)] data-[state=checked]:bg-[var(--foreground)]",
          )}
          data-slot="radio-card-check-shell"
          data-state={checked ? "checked" : "unchecked"}
        >
          <svg
            aria-hidden="true"
            viewBox="0 0 16 16"
            data-slot="radio-card-check"
            className="size-3 transform-gpu"
            fill="none"
          >
            <path
              data-slot="radio-card-check-path"
              d="M3.4 8.2 6.45 11.25 12.6 4.75"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              pathLength={1}
            />
          </svg>
        </div>
        {eyebrow ? (
          <p className="mb-2 text-[11px] font-semibold uppercase tracking-[0.07em] text-[var(--muted-foreground)]">
            {eyebrow}
          </p>
        ) : null}
        {leading ? (
          <div className="mb-3 grid size-9 place-items-center rounded-xl border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3.5%,var(--background))] text-[var(--foreground)] [&_svg]:size-[18px]">
            {leading}
          </div>
        ) : null}
        <span className="block min-w-0 pr-7">
          <span
            className={cn(
              "block font-medium leading-snug tracking-[-0.015em] text-[var(--foreground)]",
              labelSizes[radioSize],
              labelClassName,
            )}
          >
            {label}
          </span>
          {description ? (
            <span
              id={descriptionId}
              className={cn(
                "mt-1.5 block text-[12px] leading-[1.45] text-[var(--muted-foreground)]",
                descriptionClassName,
              )}
            >
              {description}
            </span>
          ) : null}
          {trailing ? (
            <span className="mt-3 inline-flex items-center rounded-md border border-[var(--border)] bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))] px-2 py-0.5 text-[11px] font-medium tracking-[0.01em] text-[var(--muted-foreground)]">
              {trailing}
            </span>
          ) : null}
        </span>
      </label>
    );
  },
);

RadioCard.displayName = "RadioCard";
